"""Create the review specification and comparisons from real saved evidence."""
from pathlib import Path
from PIL import Image,ImageDraw,ImageFont
import json,hashlib,math
ROOT=Path(__file__).resolve().parents[2];out=ROOT/'.runtime/art-library/hull/r001';lib=ROOT/'assets/art-library'
def read(name):return json.loads((out/name).read_text())
components=read('components.json');placements=read('wayfarer.json')['parts'];geometry=read('geometry-validation.json');inventory=read('inventory.json')
purposes={'floor-square':'Reusable cabin deck tile; supports seated and standing crew.','floor-corner45':'Triangular infill deck for a diagonal perimeter; no visual wedge masquerading as a cockpit.','hull-straight':'Lower opaque side wall with service cartridge and seam details.','hull-diagonal45':'Lower 45 degree shoulder, built into a 2 x 2 m grid footprint.','hull-diagonal2to1':'Shallower 26.565 degree wall in a 4 x 2 m footprint; separate sample for longer bows.','bow-transom':'Flat front armour panel with editable ship-name decal layer and mapped finish.','canopy-straight':'Upper transparent vision panel, structural mullions and emissive marker rail.','canopy-diagonal45':'Matching plan-diagonal glazing; distinct from the lower opaque wall.','roof-square':'Detachable studless cockpit roof tile; shares the deck grid.','roof-corner45':'Triangular removable roof closure over each diagonal shoulder.'}
masses={'floor-square':100,'floor-corner45':50,'hull-straight':180,'hull-diagonal45':250,'hull-diagonal2to1':395,'bow-transom':190,'canopy-straight':95,'canopy-diagonal45':135,'roof-square':80,'roof-corner45':40}
for c,g in zip(components,geometry):
 c['purpose']=purposes[c['slug']];c['geometry']=g;c['placed_object_ids']=[p['id'] for p in placements if p['assetId']==c['id']];c['proposed_stats']={'mass_kg':masses[c['slug']],'hit_points':180 if c['slug'].startswith('canopy') else 450 if c['category']=='wall' else 250,'power_w':3 if c['slug'].startswith('canopy') else 0,'status':'proposal only; not approved, balanced, or implemented authority'}
 c['crew_service_clearance_m']=.8 if c['category']=='wall' else 0;c['reference_ids']=['3d-rpg-after--wayfarer-cockpit-canopy' if 'canopy' in c['slug'] else '3d-rpg-after--wayfarer-front-nameplate' if c['slug']=='bow-transom' else '3d-rpg-after--wayfarer-exterior-red-service-panel','3d-rpg-after--wayfarer-target-cutaway']
 c['ports_proposed']=[{'id':'A','position_m':[0,0,0]},{'id':'B','position_m':[c['nominal_dimensions_m'][0],2 if 'diagonal' in c['slug'] else 0,0]}] if c['category']=='wall' else [{'id':'GRID_ORIGIN','position_m':[0,0,0]}]
 c['interfaces_status']='Descriptive source interfaces; not authority sockets or a pressure-boundary solver.'
triangles=sum(next((g['triangles'] for g in geometry if next(c for c in components if c['slug']==g['slug'])['id']==p['assetId']),0) for p in placements)
spec={'design_id':'shipyard.hull.pilot-section','revision':1,'status':'unsigned review, no publication','components':components,'assembly':{'rear_connection_x_m':[-5,5],'rear_y_m':5,'front_y_m':9,'front_flat_width_m':6,'deck_top_m':.1875,'roof_underside_m':2.625,'standing_clearance_m':2.4375,'crew_requirement':'Preserve current pilot seat and console; maintain 0.8 m service/entry route from open rear. Full animated crew sweep remains unverified.','equipment_preserved':[p for p in placements if not p['id'].startswith('pilot-review')],'module_grid_m':2,'placement_snap_m':.03125,'proxy_cell_m':.0625,'rotation_rule':'Only quarter-turns; 45 and 26.565 degree plan slopes live inside component geometry.','native_hull_triangles_all_35_placements':triangles,'separate_sample':'4 x 2 m shallow diagonal at [7,5,.1875], not attached to cabin'},'materials':{'source':'Editable Blender Principled nodes with packed textures. Separate RGBA nameplate-decal.png and source recipe.','states':['clean','worn','damaged'],'maps':['512 x 512 base colour','512 x 512 roughness','512 x 512 OpenGL +Y tangent normal','editable height source','RGBA decal mask; baked to marked-base for GLB'],'glazing':'Alpha BLEND 0.32; no transmission/refraction. Dedicated opaque solid is occupancy only.','emission':'Canopy rails are emissive PBR. No new point lights added.','scope':'States are exact review GLB variants, not a new decal-placement UI, reactive damage, holes, collision changes or server mechanics. Runtime per-placement decal/material selection remains to implement after design review.'},'remaining_differences':['Reference has a more sloped canopy and shaped roof shoulders; first grid kit is upright and flat-roofed.','Canopy junction seals and rear adapter to the complete existing hull need a follow-up integration pass; this rear-open study does not claim airtightness.','Panel maps repeat their damage pattern; next finish pass needs varied masks, world-space impact placement and finer worn-edge control.','Front reference hardware, recessed red service panels and blue frame proportions need more refinement.','Animated crew clearance, authority sockets, pressure, structural damage and whole-ship flight acceptance are not implemented or validated by this isolated study.'],'pipeline':{'visual':'Blender authored chamfered editable surfaces → textured native GLB → actual Shipyard','occupancy':'Separate closed opaque Blender proxies → actual voxelize_blender.py → VoxelVolume/encodeVoxels/meshChunk → actual placementError','publication':'No runtime catalog, source replacement, live draft or database write.'},'internal_iteration_history':[{'attempt':'attempt-01','retained':'Editable source, original open and closed Blender render and original recipe inside archive','findings':'Roof cap was coplanar and rendered black regions; ship-name plate repeated three times; endpoint rail extended past boundary.','correction':'Sank redundant roof cap below external surface, used one central marked transom and straight neighbouring panels, inset canopy endpoints. Blender denoiser unavailable; render with native Cycles samples instead.'}]}
(out/'specification.json').write_text(json.dumps(spec,indent=2)+'\n')
def board(panels,name,w=700,h=600):
 canvas=Image.new('RGB',(w*len(panels),h),'#152b38');draw=ImageDraw.Draw(canvas);font=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',18)
 for i,(path,label) in enumerate(panels):
  im=Image.open(path).convert('RGBA');im.thumbnail((w-20,h-65));canvas.paste(im,(i*w+(w-im.width)//2,55+(h-65-im.height)//2),im);draw.text((i*w+15,16),label,fill='white',font=font)
 canvas.save(out/name)
ref=lib/'assets/3d-rpg-after--wayfarer-target-cutaway/revisions/r000/reference.png'
board([(ref,'Exact target reference'),(out/'cutout.png','Blender / pilot kit r001'),(out/'runtime-clean.png','Actual Shipyard / isolated review')],'comparison.png',800,720)
board([(out/f'runtime-{s}.png','Actual Shipyard / '+s) for s in ['clean','worn','damaged']],'material-comparison.png',700,540)
board([(out/'maps'/n,label) for n,label in [('nameplate-decal.png','Editable RGBA decal'),('damaged-base.png','Damaged colour map'),('damaged-normal.png','Tangent-space normal'),('damaged-roughness.png','Roughness')]],'map-board.png',400,450)
canvas=Image.new('RGB',(1500,850),'#152b38');draw=ImageDraw.Draw(canvas)
for i,c in enumerate(components):
 im=Image.open(out/c['slug']/'cutout.png').convert('RGBA');im.thumbnail((295,350));x=i%5*300;y=i//5*425;canvas.paste(im,(x+(300-im.width)//2,y+45),im);draw.text((x+12,y+10),c['slug'],fill='white');draw.text((x+12,y+395),str(c['geometry']['triangles'])+' triangles',fill='#91cedd')
canvas.save(out/'component-board.png')
# A native vector diagram derived from actual assembly coordinates, not an altered screenshot.
svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1100" height="670" viewBox="0 0 1100 670"><rect width="1100" height="670" fill="#142a36"/><g font-family="sans-serif" fill="#e5eff5"><text x="35" y="38" font-size="24">Pilot bay r001 · actual 2 m module grid</text><text x="35" y="64" font-size="15">Diagonals are part geometry. Placements rotate in 90° steps; snap = 1/32 m.</text></g>']
def point(x,y):return (550+x*75,500-(y-5)*75)
for x in range(-5,6,2):
 a,b=point(x,5),point(x,9);svg.append(f'<path d="M{a[0]} {a[1]} L{b[0]} {b[1]}" stroke="#496171"/>')
for y in [5,7,9]:
 a,b=point(-5,y),point(5,y);svg.append(f'<path d="M{a[0]} {a[1]} L{b[0]} {b[1]}" stroke="#496171"/>')
pts=' '.join(f'{x},{y}' for x,y in [point(-5,5),point(-5,7),point(-3,9),point(3,9),point(5,7),point(5,5)])
svg.append(f'<polyline points="{pts}" fill="#59717b" fill-opacity=".2" stroke="#74e1eb" stroke-width="9"/>')
for x,y,label in [(0,9.55,'6 m flat bow'),(-5,7.7,'45°'),(4.5,7.7,'45°'),(-1,4.55,'10 m open cabin interface'),(-1,7,'Crew access from rear'),(-1,6,'Existing pilot seat')]:
 px,py=point(x,y);svg.append(f'<text x="{px}" y="{py}" fill="#eff6fa" font-family="sans-serif" font-size="18">{label}</text>')
svg.append('<text x="35" y="615" fill="#b8cdd6" font-family="sans-serif" font-size="17">Deck top 0.1875 m · roof underside 2.625 m · standing clearance 2.4375 m</text></svg>');(out/'grid-layout.svg').write_text(''.join(svg))
# Hash the published baseline without replacing it; concurrent work is reported, not reverted.
baseline={p:{'before':sha,'now':hashlib.sha256((ROOT/p).read_bytes()).hexdigest()} for p,sha in inventory['hashes'].items()}
(out/'publication-isolation.json').write_text(json.dumps({'published_by_this_task':False,'baseline_hashes':baseline,'unchanged':all(v['before']==v['now'] for v in baseline.values())},indent=2))
print('Documented 10 modules,',triangles,'placed hull triangles')
